<?php
require_once __DIR__.'/../includes/functions.php';require_role('admin');require_once __DIR__.'/../config/database.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$target=(int)($_POST['user_id']??0);$role=$_POST['role']??'student';$status=$_POST['account_status']??'active';if(!in_array($role,['student','mentor','admin'],true)||!in_array($status,['active','blocked'],true)){flash('Invalid account settings.','error');redirect('admin/users.php');}if($target===(int)current_user()['user_id']&&$status==='blocked'){flash('You cannot block your own signed-in account.','error');redirect('admin/users.php');}$st=$pdo->prepare('UPDATE users SET role=?,account_status=? WHERE user_id=?');$st->execute([$role,$status,$target]);flash('Account settings updated.');redirect('admin/users.php');}
$q=trim($_GET['q']??'');$params=[];$sql='SELECT user_id,full_name,email,department,role,account_status,created_at FROM users';if($q!==''){$sql.=' WHERE full_name LIKE ? OR email LIKE ?';$params=['%'.$q.'%','%'.$q.'%'];}$sql.=' ORDER BY created_at DESC LIMIT 200';$st=$pdo->prepare($sql);$st->execute($params);$users=$st->fetchAll();$pageTitle='User management';$active='admin';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Administrator tools</span><h1 class="h1">User management</h1><p>Manage platform roles and account access. Assign mentor access only to trusted reviewers.</p></div><a class="btn btn-outline" href="<?=h(url('admin/dashboard.php'))?>">← Admin overview</a></div><form class="filters" method="get"><div class="search-box"><span>⌕</span><input name="q" value="<?=h($q)?>" placeholder="Search by name or email"></div><button class="btn btn-primary btn-sm">Search</button></form><section class="card card-pad"><div class="table-wrap"><table class="table"><thead><tr><th>Account</th><th>Department</th><th>Role / status</th><th>Update access</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=h($u['full_name'])?></strong><div class="tiny muted"><?=h($u['email'])?> · joined <?=date('d M Y',strtotime($u['created_at']))?></div></td><td><?=h($u['department']?:'—')?></td><td><span class="pill pill-blue"><?=h(ucfirst($u['role']))?></span> <span class="pill <?=$u['account_status']==='active'?'pill-green':'pill-red'?>"><?=h(ucfirst($u['account_status']))?></span></td><td><form method="post" class="row" style="gap:6px;flex-wrap:wrap"><?=csrf_field()?><input type="hidden" name="user_id" value="<?=(int)$u['user_id']?>"><select class="task-select" name="role"><option value="student" <?=$u['role']==='student'?'selected':''?>>Student</option><option value="mentor" <?=$u['role']==='mentor'?'selected':''?>>Mentor</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Admin</option></select><select class="task-select" name="account_status"><option value="active" <?=$u['account_status']==='active'?'selected':''?>>Active</option><option value="blocked" <?=$u['account_status']==='blocked'?'selected':''?>>Blocked</option></select><button class="btn btn-outline btn-sm">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php if(!$users):?><div class="empty-state"><h2>No matching accounts</h2><p>Try a different search term.</p></div><?php endif;?></section></div></main><?php include __DIR__.'/../includes/footer.php';?>
